local photoLoaded, photoError = pcall(function()
    local indexBytes = decodeBase64(PHOTO_INDEX_BASE64)
    local paletteBytes = decodeBase64(PHOTO_PALETTE_BASE64)
    local editableImage = AssetService:CreateEditableImage({
        Size = Vector2.new(PHOTO_WIDTH, PHOTO_HEIGHT),
    })
    if not editableImage then
        error("Roblox não disponibilizou memória para a imagem.")
    end

    local pixelCount = PHOTO_WIDTH * PHOTO_HEIGHT
    local expectedBytes = math.ceil(pixelCount * 7 / 8)
    if #indexBytes < expectedBytes or #paletteBytes < 128 * 3 then
        error("Dados da imagem embutida incompletos.")
    end

    local pixels = buffer.create(pixelCount * 4)
    local bitBuffer, bitCount, sourceIndex = 0, 0, 1
    for pixel = 0, pixelCount - 1 do
        while bitCount < 7 do
            bitBuffer = bitBuffer * 256 + string.byte(indexBytes, sourceIndex)
            bitCount += 8
            sourceIndex += 1
        end
        bitCount -= 7
        local colorIndex = math.floor(bitBuffer / (2 ^ bitCount)) % 128
        bitBuffer %= 2 ^ bitCount

        local paletteOffset = colorIndex * 3
        local destination = pixel * 4
        buffer.writeu8(pixels, destination, string.byte(paletteBytes, paletteOffset + 1))
        buffer.writeu8(pixels, destination + 1, string.byte(paletteBytes, paletteOffset + 2))
        buffer.writeu8(pixels, destination + 2, string.byte(paletteBytes, paletteOffset + 3))
        buffer.writeu8(pixels, destination + 3, 255)

        if pixel > 0 and pixel % (PHOTO_WIDTH * 20) == 0 then
            task.wait()
        end
    end

    editableImage:WritePixelsBuffer(Vector2.zero, Vector2.new(PHOTO_WIDTH, PHOTO_HEIGHT), pixels)
    backgroundPhoto.ImageContent = Content.fromObject(editableImage)
end)

if not photoLoaded then
    backgroundPhoto.Visible = false
    warn("[NOVA] A imagem embutida precisa das APIs de imagem editável do Roblox habilitadas. " .. tostring(photoError))
end

