task.spawn(function()
    local corners = {
        UDim2.new(1, -10, 0, 10),
        UDim2.new(1, -10, 1, -10),
        UDim2.new(0, 10, 1, -10),
        UDim2.new(0, 10, 0, 10),
    }
    while orbitDot.Parent and orbitGlow.Parent do
        for _, nextPosition in ipairs(corners) do
            if not orbitDot.Parent then
                return
            end
            local info = TweenInfo.new(1.1, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut)
            local glowMove = TweenService:Create(orbitGlow, info, {Position = nextPosition})
            local dotMove = TweenService:Create(orbitDot, info, {Position = nextPosition})
            glowMove:Play()
            dotMove:Play()
            dotMove.Completed:Wait()
        end
    end
end)

